/*<info serverAlias="DBRMS-bodb_RMS" isFunction="0" isNested="1"></info>*/
ALTER PROCEDURE [dbo].[Task_RMS_SumData_rmSumByBettype]
	@winlostdate	SMALLDATETIME
	,@ErrCode		INT = 0 OUTPUT
	,@ErrMsg		VARCHAR(4000) = '' OUTPUT
AS

/*
	Created: 20200601@Percy
	DB: DBRMS-bodb_RMS
	Task: RMS - Sum data of rmSumByBettype

	Revisions:
		- 20200601@Percy: Initialize SP [RedmineID: #135326]
		- 20210111@Danny: Enhance performance (get data from bettrans_bk) [RedmineID: #123157]
		- 20210607@Danny: Move 'Saba789' to Credit Site  [RedmineID: #153874]
		- 20210809@Danny: Add column bettype,betteam into rmBettransm_bk [RedmineID: #159304]
		- 20220301@Danny: Support basketball Sport type data [RedmineID: #169072]
		- 20240315@Cherry: Enhance League Bettype report (#197684)
		- 20240702@Jaden: Enhance performance (#207279)
		- 20241016@Cherry: Hot fix (#212259)
		- 20241030@Cherry: Add Single Match Parlay (#209293)
		- 20250212@Cherry: hot fix (#217757)
		- 20250214@Cherry: Support direct member (#215427)
		- 20251016@Cherry: Move sites NovaCasino, SEAL888 from Deposit to Credit (#241763)
		- 20251020@Cherry: Integrate Hybrid Parlay (#242165)

*/

BEGIN
	SET NOCOUNT ON

	DECLARE @WLDate DATE
	SELECT  @WLDate = @winlostdate

	DECLARE @MBBU TABLE (BalanceUpDay SMALLDATETIME, MoveBetsDay SMALLDATETIME)
	INSERT INTO @MBBU (BalanceUpDay, MoveBetsDay)
	EXEC bodb02.dbo.Age_SelBalanceUpDay

	DECLARE @BalanceUpDay SMALLDATETIME, @MoveBetsDay SMALLDATETIME
	SELECT  @BalanceUpDay = BalanceUpDay, @MoveBetsDay = MoveBetsDay FROM @MBBU

	IF @winlostdate < @BalanceUpDay
		RETURN

	CREATE TABLE #rmSumByBettype
	(
		bettype				SMALLINT
		,ParlayType			TINYINT
		,IsDeposit			BIT
		,leagueId			INT
		,BetCount			INT
		,WonCount			INT
		,LoseCount			INT
		,DrawCount			INT
		,MainBetCount		INT
		,MainWonCount		INT
		,MainLoseCount		INT
		,MainDrawCount		INT
		,MainStake			MONEY
		,MainTurnover		MONEY
		,MainTurnoverNoDraw	MONEY
		,MainMemberWinloss	MONEY
		,MainMemberComm		MONEY
		,MainHouseWinloss	MONEY
	)
	CREATE CLUSTERED INDEX CIX_rmSumByBettype ON #rmSumByBettype (bettype, ParlayType)

	CREATE TABLE #bettrans(refno BIGINT, ParlayType TINYINT, IsDeposit BIT, statusID TINYINT, TotalSelection SMALLMONEY, stake MONEY, winloss MONEY, playercomm MONEY, HouseWinloss MONEY)

	IF @winlostdate > @MoveBetsDay
	BEGIN
		INSERT INTO #bettrans (refno, ParlayType, IsDeposit, statusID, TotalSelection, stake, winloss, playercomm, HouseWinloss)
		SELECT refno, 
			CASE WHEN betteam = N'1' AND oddsspread = 3 THEN 9 --Hybrid Parlay
				WHEN betteam = N'1' THEN 2 --Mix Parlay
				ELSE 3 -- Combo Parlay
			END ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END, statusID, hdp2, 
			stake*actualrate, (winlost-actual_stake)*actualrate, playercomm*actualrate, 
		CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END
		FROM dbo.rmBettrans r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 29
			AND r.liveawayscore IN (1,2, 3) -- soccer
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
	END
	ELSE
	BEGIN
		INSERT INTO #bettrans (refno, ParlayType, IsDeposit, statusID, TotalSelection, stake, winloss, playercomm, HouseWinloss)
		SELECT refno, 
			CASE WHEN betteam = N'1' AND oddsspread = 3 THEN 9 --Hybrid Parlay
				WHEN betteam = N'1' THEN 2 --Mix Parlay
				ELSE 3 -- Combo Parlay
			END ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END, 
			statusID, hdp2, stake*actualrate, (winlost-actual_stake)*actualrate, playercomm*actualrate, 
		CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END
		FROM dbo.rmBettrans_Old r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 29
			AND r.liveawayscore IN (1, 2, 3) -- soccer
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20

	END

    CREATE UNIQUE CLUSTERED INDEX IX_bettrans ON #bettrans (refno)

    CREATE TABLE #match (refno BIGINT, sporttype INT, bettype INT ,leagueid INT, matchid INT, statusID TINYINT, winlostdate SMALLDATETIME)

    INSERT INTO #match (refno, sporttype, bettype, leagueid, matchid, statusID, winlostdate)
    SELECT refno, sporttype, bm.bettype, m.leagueid, m.matchid, bm.statusID, winlostdate
    FROM bodb02.dbo.bettransm bm WITH (NOLOCK)
        INNER JOIN bodb02.dbo.match m WITH (NOLOCK) ON bm.matchid = m.matchid
    WHERE m.sporttype IN (1,2) AND (bm.winlostdate > @MoveBetsDay OR bm.winlostdate IS NULL)
      AND refno IN (SELECT refno FROM #bettrans)

    INSERT INTO #match (refno, sporttype, bettype, leagueid, matchid, statusID, winlostdate)
    SELECT refno, sporttype, bm.bettype, m.leagueid, m.matchid, bm.statusID, winlostdate
    FROM bodb02.dbo.bettransm14 bm WITH (NOLOCK)
        INNER JOIN bodb02.dbo.match14 m WITH (NOLOCK) ON bm.matchid = m.matchid
    WHERE m.sporttype IN (1,2) AND bm.winlostdate BETWEEN @BalanceUpDay AND  @MoveBetsDay
      AND refno IN (SELECT refno FROM #bettrans)

	--assist param to guide better plan (avoid index scan of rmBettrans_bk)
	DECLARE @minRef BIGINT
    SELECT @minRef = MIN(refno) FROM #bettrans

    INSERT INTO #match (refno, sporttype, bettype, leagueid, matchid, statusID, winlostdate)
    SELECT refno, sporttype, bm.bettype, m.leagueid, bm.matchid, bm.statusID, winlostdate
    FROM dbo.rmBettransm_bk bm WITH (NOLOCK)
        INNER JOIN dbo.rmMatch_bk m WITH (NOLOCK) ON bm.matchid = m.matchid
    WHERE m.sporttype IN (1,2) AND bm.winlostdate < @BalanceUpDay
      AND refno IN (SELECT refno FROM #bettrans)
	  AND refno >= @minRef

    CREATE CLUSTERED INDEX IX_match ON #match (refno, sporttype)

	CREATE TABLE #tmp1 (refno BIGINT, bettype INT , leagueid INT, matchid INT, statusID TINYINT, RowNum BIGINT)
	INSERT INTO #tmp1 (refno, bettype, leagueid, matchid, statusID, RowNum)
	SELECT refno, bettype, LeagueId, matchid, statusID, 
		ROW_NUMBER() OVER(PARTITION BY refno, bettype, LeagueId, matchid ORDER BY (SELECT NULL)) AS RowNum
	FROM #match

	INSERT INTO #rmSumByBettype (bettype, ParlayType, IsDeposit, LeagueId, BetCount, WonCount, LoseCount, DrawCount, MainBetCount, MainWonCount, MainLoseCount, MainDrawCount, MainStake, MainTurnover, MainTurnoverNoDraw, MainMemberWinloss, MainMemberComm, MainHouseWinloss)
	SELECT
		t.bettype
		,b.ParlayType
		,b.IsDeposit
		,t.LeagueId
		,BetCount			= SUM(1)
		,WonCount			= SUM(CASE WHEN t.statusID = 112 THEN 1 ELSE 0 END)
		,LoseCount			= SUM(CASE WHEN t.statusID = 113 THEN 1 ELSE 0 END)
		,DrawCount			= SUM(CASE WHEN t.statusID = 111 THEN 1 ELSE 0 END)
		,MainBetCount		= SUM(CASE WHEN t.rn = 1 THEN 1 ELSE 0 END)
		,MainWonCount		= SUM(CASE WHEN t.rn = 1 AND b.statusID = 112 THEN 1 ELSE 0 END)
		,MainLoseCount		= SUM(CASE WHEN t.rn = 1 AND b.statusID = 113 THEN 1 ELSE 0 END)
		,MainDrawCount		= SUM(CASE WHEN t.rn = 1 AND b.statusID = 111 THEN 1 ELSE 0 END)
		,MainStake			= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END ELSE 0 END)
		,MainTurnover		= SUM(CASE WHEN t.rn = 1 AND b.statusID IN (111, 112, 113) THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END ELSE 0 END)
		,MainTurnoverNoDraw	= SUM(CASE WHEN t.rn = 1 AND b.statusID IN (112, 113) THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END ELSE 0 END)
		,MainWinloss		= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.winloss/b.TotalSelection END ELSE 0 END)
		,MainComm			= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.playercomm/b.TotalSelection END ELSE 0 END) 
		,MainHouseWinloss	= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.HouseWinloss/b.TotalSelection END ELSE 0 END)
	FROM #bettrans b
		CROSS APPLY (
			SELECT bettype, LeagueId, statusID, ROWNum AS rn
			FROM #tmp1
            WHERE b.refno = #tmp1.refno
		) t
	GROUP BY
		t.bettype
		,b.ParlayType
		,b.IsDeposit
		,t.LeagueId

	CREATE TABLE #tmp2 (refno BIGINT, bettype INT, statusID TINYINT, RowNum BIGINT)
	INSERT INTO #tmp2 (refno, bettype, statusID, RowNum)
	SELECT refno, bettype, statusID, 
		ROW_NUMBER() OVER(PARTITION BY refno, bettype, matchid ORDER BY (SELECT NULL)) AS RowNum
	FROM #match
	WHERE sporttype = 1

	INSERT INTO #rmSumByBettype (bettype, ParlayType, IsDeposit, LeagueId, BetCount, WonCount, LoseCount, DrawCount, MainBetCount, MainWonCount, MainLoseCount, MainDrawCount, MainStake, MainTurnover, MainTurnoverNoDraw, MainMemberWinloss, MainMemberComm, MainHouseWinloss)
	SELECT
		t.bettype
		,b.ParlayType
		,b.IsDeposit
		,0  -- soccer only
		,BetCount			= SUM(1)
		,WonCount			= SUM(CASE WHEN t.statusID = 112 THEN 1 ELSE 0 END)
		,LoseCount			= SUM(CASE WHEN t.statusID = 113 THEN 1 ELSE 0 END)
		,DrawCount			= SUM(CASE WHEN t.statusID = 111 THEN 1 ELSE 0 END)
		,MainBetCount		= SUM(CASE WHEN t.rn = 1 THEN 1 ELSE 0 END)
		,MainWonCount		= SUM(CASE WHEN t.rn = 1 AND b.statusID = 112 THEN 1 ELSE 0 END)
		,MainLoseCount		= SUM(CASE WHEN t.rn = 1 AND b.statusID = 113 THEN 1 ELSE 0 END)
		,MainDrawCount		= SUM(CASE WHEN t.rn = 1 AND b.statusID = 111 THEN 1 ELSE 0 END)
		,MainStake			= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END ELSE 0 END)
		,MainTurnover		= SUM(CASE WHEN t.rn = 1 AND b.statusID IN (111, 112, 113) THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END ELSE 0 END)
		,MainTurnoverNoDraw	= SUM(CASE WHEN t.rn = 1 AND b.statusID IN (112, 113) THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END ELSE 0 END)
		,MainWinloss		= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.winloss/b.TotalSelection END ELSE 0 END)
		,MainComm			= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.playercomm/b.TotalSelection END ELSE 0 END) 
		,MainHouseWinloss	= SUM(CASE WHEN t.rn = 1 THEN CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.HouseWinloss/b.TotalSelection END ELSE 0 END)
	FROM #bettrans b
		CROSS APPLY (
			SELECT bettype, statusID, RowNum AS rn
			FROM #tmp2
            WHERE b.refno = #tmp2.refno
		) t                
	GROUP BY
		t.bettype
		,b.ParlayType
		,b.IsDeposit

	-- Single Match Parlay
	IF @winlostdate > @MoveBetsDay
	BEGIN
		INSERT INTO #rmSumByBettype 
			(bettype, 
			ParlayType, 
			IsDeposit, 
			LeagueId, 
			BetCount, 
			WonCount, 
			LoseCount, 
			DrawCount, 
			MainBetCount, 
			MainWonCount, 
			MainLoseCount, 
			MainDrawCount, 
			MainStake, 
			MainTurnover, 
			MainTurnoverNoDraw, 
			MainMemberWinloss, 
			MainMemberComm, 
			MainHouseWinloss)
		SELECT r.bettype, 
			4 ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END IsDeposit, 
			m.leagueid, 
			SUM(1) BetCount, 
			SUM(CASE WHEN t.Result = 'Won' THEN 1 ELSE 0 END) WonCount,
			SUM(CASE WHEN t.Result = 'Lose' THEN 1 ELSE 0 END) LoseCount,
			SUM(CASE WHEN t.Result = 'Draw' THEN 1 ELSE 0 END) DrawCount,
			COUNT(DISTINCT r.transid) MainBetCount, 
			COUNT(DISTINCT CASE WHEN r.statusID = 112 THEN r.transid ELSE NULL END) MainWonCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 113 THEN r.transid ELSE NULL END) MainLoseCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 111 THEN r.transid ELSE NULL END) MainDrawCount,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake*r.actualrate/r.hdp2 END) AS MainStake, 
			SUM(CASE WHEN r.statusID IN (111, 112, 113) THEN CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake*r.actualrate/r.hdp2 END ELSE 0 END) AS MainTurnover, 
			SUM(CASE WHEN r.statusID IN (112, 113) THEN CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake*r.actualrate/r.hdp2 END ELSE 0 END) AS MainTurnoverNoDraw, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE (winlost-actual_stake)*actualrate/r.hdp2 END) AS MainMemberWinloss,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE playercomm*actualrate/r.hdp2 END) AS MainMemberComm,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END/r.hdp2 END) AS MainHouseWinloss
		FROM dbo.rmBettrans r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.match m WITH (NOLOCK) ON r.matchid = m.matchid
			INNER JOIN bodb02.dbo.SMP_MarketSelection t WITH(NOLOCK) ON t.MatchId = r.matchid AND t.MarketId = r.betcheck
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 38			
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
		GROUP BY r.bettype, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END, 
			m.leagueid

		INSERT INTO #rmSumByBettype 
			(bettype, 
			ParlayType, 
			IsDeposit, 
			LeagueId, 
			BetCount, 
			WonCount, 
			LoseCount, 
			DrawCount, 
			MainBetCount, 
			MainWonCount, 
			MainLoseCount, 
			MainDrawCount, 
			MainStake, 
			MainTurnover, 
			MainTurnoverNoDraw, 
			MainMemberWinloss, 
			MainMemberComm, 
			MainHouseWinloss)
		SELECT r.bettype, 
			4 ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END IsDeposit, 
			0 leagueid, 
			SUM(1) BetCount, 
			SUM(CASE WHEN t.Result = 'Won' THEN 1 ELSE 0 END) WonCount,
			SUM(CASE WHEN t.Result = 'Lose' THEN 1 ELSE 0 END) LoseCount,
			SUM(CASE WHEN t.Result = 'Draw' THEN 1 ELSE 0 END) DrawCount,
			COUNT(DISTINCT r.transid) MainBetCount, 
			COUNT(DISTINCT CASE WHEN r.statusID = 112 THEN r.transid ELSE NULL END) MainWonCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 113 THEN r.transid ELSE NULL END) MainLoseCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 111 THEN r.transid ELSE NULL END) MainDrawCount,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake*r.actualrate/r.hdp2 END) AS MainStake, 
			SUM(CASE WHEN r.statusID IN (111, 112, 113) THEN CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake*r.actualrate/r.hdp2 END ELSE 0 END) AS MainTurnover, 
			SUM(CASE WHEN r.statusID IN (112, 113) THEN r.stake*r.actualrate/r.hdp2 ELSE 0 END) AS MainTurnoverNoDraw, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE (winlost-actual_stake)*actualrate/r.hdp2 END) AS MainMemberWinloss,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE playercomm*actualrate/r.hdp2 END) AS MainMemberComm,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END/r.hdp2 END) AS MainHouseWinloss
		FROM dbo.rmBettrans r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.match m WITH (NOLOCK) ON r.matchid = m.matchid
			INNER JOIN bodb02.dbo.SMP_MarketSelection t WITH(NOLOCK) ON t.MatchId = r.matchid AND t.MarketId = r.betcheck
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 38			
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
			AND m.sporttype = 1
		GROUP BY r.bettype, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END
	END

	IF @winlostdate BETWEEN @BalanceUpDay AND @MoveBetsDay
	BEGIN
		INSERT INTO #rmSumByBettype 
			(bettype, 
			ParlayType, 
			IsDeposit, 
			LeagueId, 
			BetCount, 
			WonCount, 
			LoseCount, 
			DrawCount, 
			MainBetCount, 
			MainWonCount, 
			MainLoseCount, 
			MainDrawCount, 
			MainStake, 
			MainTurnover, 
			MainTurnoverNoDraw, 
			MainMemberWinloss, 
			MainMemberComm, 
			MainHouseWinloss)
		SELECT r.bettype, 
			4 ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END IsDeposit, 
			m.leagueid, 
			SUM(1) BetCount, 
			SUM(CASE WHEN t.Result = 'Won' THEN 1 ELSE 0 END) WonCount,
			SUM(CASE WHEN t.Result = 'Lose' THEN 1 ELSE 0 END) LoseCount,
			SUM(CASE WHEN t.Result = 'Draw' THEN 1 ELSE 0 END) DrawCount,
			COUNT(DISTINCT r.transid) MainBetCount, 
			COUNT(DISTINCT CASE WHEN r.statusID = 112 THEN r.transid ELSE NULL END) MainWonCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 113 THEN r.transid ELSE NULL END) MainLoseCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 111 THEN r.transid ELSE NULL END) MainDrawCount,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake*r.actualrate/r.hdp2 END) AS MainStake, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN r.statusID IN (111, 112, 113) THEN r.stake*r.actualrate/r.hdp2 ELSE 0 END END) AS MainTurnover, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN r.statusID IN (112, 113) THEN r.stake*r.actualrate/r.hdp2 ELSE 0 END END) AS MainTurnoverNoDraw, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE (winlost-actual_stake)*actualrate/r.hdp2 END) AS MainMemberWinloss,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE playercomm*actualrate/r.hdp2 END) AS MainMemberComm,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END/r.hdp2 END) AS MainHouseWinloss
		FROM dbo.rmBettrans_Old r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.match14 m WITH (NOLOCK) ON r.matchid = m.matchid
			INNER JOIN bodb02.dbo.SMP_MarketSelection14 t WITH(NOLOCK) ON t.MatchId = r.matchid AND t.MarketId = r.betcheck
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 38			
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
		GROUP BY r.bettype, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END, 
			m.leagueid

		INSERT INTO #rmSumByBettype 
			(bettype, 
			ParlayType, 
			IsDeposit, 
			LeagueId, 
			BetCount, 
			WonCount, 
			LoseCount, 
			DrawCount, 
			MainBetCount, 
			MainWonCount, 
			MainLoseCount, 
			MainDrawCount, 
			MainStake, 
			MainTurnover, 
			MainTurnoverNoDraw, 
			MainMemberWinloss, 
			MainMemberComm, 
			MainHouseWinloss)
		SELECT r.bettype, 
			4 ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END IsDeposit, 
			0 leagueid, 
			SUM(1) BetCount, 
			SUM(CASE WHEN t.Result = 'Won' THEN 1 ELSE 0 END) WonCount,
			SUM(CASE WHEN t.Result = 'Lose' THEN 1 ELSE 0 END) LoseCount,
			SUM(CASE WHEN t.Result = 'Draw' THEN 1 ELSE 0 END) DrawCount,
			COUNT(DISTINCT r.transid) MainBetCount, 
			COUNT(DISTINCT CASE WHEN r.statusID = 112 THEN r.transid ELSE NULL END) MainWonCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 113 THEN r.transid ELSE NULL END) MainLoseCount,
			COUNT(DISTINCT CASE WHEN r.statusID = 111 THEN r.transid ELSE NULL END) MainDrawCount,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake*r.actualrate/r.hdp2 END) AS MainStake, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN r.statusID IN (111, 112, 113) THEN r.stake*r.actualrate/r.hdp2 ELSE 0 END END) AS MainTurnover, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN r.statusID IN (112, 113) THEN r.stake*r.actualrate/r.hdp2 ELSE 0 END END) AS MainTurnoverNoDraw, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE (winlost-actual_stake)*actualrate/r.hdp2 END) AS MainMemberWinloss,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE playercomm*actualrate/r.hdp2 END) AS MainMemberComm,
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END/r.hdp2 END) AS MainHouseWinloss
		FROM dbo.rmBettrans_Old r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.match14 m WITH (NOLOCK) ON r.matchid = m.matchid
			INNER JOIN bodb02.dbo.SMP_MarketSelection14 t WITH(NOLOCK) ON t.MatchId = r.matchid AND t.MarketId = r.betcheck
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 38			
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
			AND m.sporttype = 1
		GROUP BY r.bettype, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END
	END
	
	-- End of SMP

	BEGIN TRY
		DELETE dbo.rmSumByBettype WITH (ROWLOCK, UPDLOCK) WHERE winlostdate = @WLDate

		INSERT INTO dbo.rmSumByBettype (winlostdate,bettype,ParlayType,IsDeposit,leagueId,BetCount,WonCount,DrawCount,LoseCount,MainBetCount,MainWonCount,MainLoseCount,MainDrawCount,MainStake,MainTurnover,MainTurnoverNoDraw,MainMemberWinloss,MainMemberComm,MainHouseWinloss)
		SELECT @WLDate,bettype,ParlayType,IsDeposit,leagueId,SUM(BetCount),SUM(WonCount),SUM(DrawCount),SUM(LoseCount),SUM(MainBetCount),SUM(MainWonCount),SUM(MainLoseCount),SUM(MainDrawCount),SUM(MainStake),SUM(MainTurnover),SUM(MainTurnoverNoDraw),SUM(MainMemberWinloss),SUM(MainMemberComm),SUM(MainHouseWinloss)
		FROM #rmSumByBettype
		GROUP BY bettype,ParlayType,IsDeposit,leagueId
	END TRY
	BEGIN CATCH
		SELECT @ErrCode = ERROR_NUMBER(), @ErrMsg = ERROR_MESSAGE()
		--RETURN
	END CATCH

	DROP TABLE #rmSumByBettype
	DROP TABLE #bettrans
	DROP TABLE #match
	DROP TABLE #tmp1
	DROP TABLE #tmp2

END
